// Read-route visibility classification: every GET route registered by createApp(), exactly once.
// Enforced by readRouteVisibilityClassification.structure.test.ts from runtime route registration
// (routeRegistrationCapture.ts with { methods: "read" }), like routeAuthorityClassification.ts for writes.
//
// Entries:
//   unified          - decides visibility through services/visibilityService (canView / visibleRootChannelIds /
//                      visibleConversationSql)
//   legacy:<check>   - returns conversation-homed objects (messages, threads, channels, attachments, tasks,
//                      reactions, members of a channel, saved messages, inbox, ...) through an older check, named
//                      after the function that decides; this list is the migration backlog
//   none             - returns no conversation-homed objects
//
// Visibility is not the archived filter: whether a route lists archived conversations stays its own choice.

import { appAgentApiRoutesOf, firstPartyAppAgentApis } from "@botiverse/raft-shared";

export type ReadRouteVisibilityEntry = "unified" | `legacy:${string}` | "none";

export type ReadRouteClassification = { route: string; entry: ReadRouteVisibilityEntry; reason: string };

/**
 * The exact number of legacy entries: a ratchet. Lower it in the same change that migrates a route to the
 * unified entry (or proves it returns no conversation objects). Never raise it to admit a new legacy read;
 * a new read route uses the unified entry.
 */
export const MAX_LEGACY_READ_ROUTES = 85;

/**
 * The exact number of `none` entries, pinned so a new `none` label (a claim that a read returns no
 * conversation objects) shows up in diff review rather than slipping in with a new route.
 */
export const EXPECTED_NONE_READ_ROUTES = 239;

