export function checkReadRouteClassification(
  registered: ReadonlyArray<{ method: string; path: string }>,
  table: readonly ReadRouteClassification[] = READ_ROUTE_VISIBILITY_CLASSIFICATION,
) {
  const registeredKeys = new Set(registered.map((route) => `${route.method} ${route.path}`));
  const seen = new Set<string>();
  const duplicates: string[] = [];
  for (const row of table) {
    if (seen.has(row.route)) duplicates.push(row.route);
    seen.add(row.route);
  }
  return {
    unclassified: [...registeredKeys].filter((key) => !seen.has(key)).sort(),
    stale: [...seen].filter((key) => !registeredKeys.has(key)).sort(),
    duplicates,
    missingReasons: table.filter((row) => row.reason.trim() === "").map((row) => row.route),
    malformedEntries: table
      .filter((row) => row.entry !== "unified" && row.entry !== "none" && !/^legacy:\S/.test(row.entry))
      .map((row) => row.route),
    legacyCount: table.filter((row) => row.entry.startsWith("legacy:")).length,
    noneCount: table.filter((row) => row.entry === "none").length,
  };
}
